-- mod-temucraft-classes (racials): racial actives and missing racials from wow-racials_v3, adapted to 3.3.5.
-- New spells 95835-95899; new racial skill line rows 32050-32149; the skill line rows of the renamed stock copies they
-- replace (31459, 31616, 31628, 31656, 31688, 31696, 31700, 31701, 31704, 31708, 31712, 31716, 31720, 31721, 31772, 31773, 31776, 31777) now teach the new spell (the core loads these rows over the DBC ones).
-- The client needs the same rows (tools/build_racial_actives.py --client). The scripts are in
-- src/racials/TemucraftRacialActives.cpp (Temucraft.Racials.Actives). Made by tools/build_racial_actives.py.
-- Re-runnable.
DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 95835 AND 95899;

DELETE FROM `skilllineability_dbc` WHERE `ID` BETWEEN 32050 AND 32149 OR `ID` IN (31459, 31616, 31628, 31656, 31688, 31696, 31700, 31701, 31704, 31708, 31712, 31716, 31720, 31721, 31772, 31773, 31776, 31777);

DELETE FROM `spell_script_names` WHERE `spell_id` BETWEEN 95835 AND 95899;

-- player-facing texts (TemucraftRacialActives.cpp; translations go in module_string_locale)
DELETE FROM `module_string` WHERE `module` = 'mod-temucraft-racial-actives';
